window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-69d67eebda036252"]={"versions": [{"id": "FIG-69d67eebda036252", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR System Template / Timing Extensions View).\n</li><li><strong>Technischer Zweck:</strong> Formale Verankerung der systemweiten Timing-Spezifikation (<code>SystemTiming</code>) an das Gesamtsystem (<code>System</code>) und dessen modulare Software-Partitionen (<code>CpSoftwareCluster</code>).\n</li><li><strong>Funktionale Einordnung:</strong> In AUTOSAR Classic Platform R20-11 ermöglicht dieses Metamodell die Spezifikation von zeitlichen Anforderungen (End-to-End-Latenzen, Event Chains, Synchronisationsbudgets) über die Grenzen unabhängig aktualisierbarer bzw. verteilter Software-Cluster hinweg.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Timing::SystemTiming</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>TimingExtension</code>.\n</li><li><em>Funktion:</em> Container für systemweite Timing-Beschreibungen (Ereignisse, Ereignisketten, Timing Constraints auf System- und Netzwerkebene).\n</li></ul>\n</li><li><strong><code>SystemTemplate::System</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>ARElement</code> und <code>AtpStructureElement</code>.\n</li><li><em>Funktion:</em> Wurzel-Entität der AUTOSAR-Systembeschreibung; aggregiert Topologie, Software-Composition, Signal-/PDU-Mappings und Systemkonfiguration.\n</li></ul>\n</li><li><strong><code>SoftwareCluster::CpSoftwareCluster</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>ARElement</code>.\n</li><li><em>Funktion:</em> Repräsentiert einen autark kompilierbaren, linkbaren oder via OTA aktualisierbaren Classic-Platform-Software-Cluster (logische Software-Partition).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>SystemTiming</code> → <code>System</code>: Unidirektionale Referenz <code>+system</code> mit Kardinalität <code>1</code> (jede <code>SystemTiming</code>-Instanz ist exakt einem definierten <code>System</code> fest zugeordnet).\n</li><li><code>System</code> → <code>CpSoftwareCluster</code>: Unidirektionale Referenz <code>+swCluster</code> mit Kardinalität <code>0..*</code>.\n</li><li><strong>Stereotypen auf <code>+swCluster</code>:</strong>\n<ul class=\"fig-list\"><li><code>«atpSplitable»</code>: Die Zuordnung von Clustern zum System kann physisch über separate ARXML-Dateien/Lieferartefakte verteilt (gesplittet) werden.\n</li><li><code>«atpVariation»</code>: Die Assoziation unterliegt der AUTOSAR-Variantentheorie (Bindung über Variant Condition Formulas zur Pre-Compile-, Link- oder Post-Build-Zeit).\n</li></ul>\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Charakter:</strong> Kein Laufzeit-Sequenzablauf. Es handelt sich um ein rein deklaratives Entwurfszeit-Modell für den ARXML-Datenaustausch.\n</li><li><strong>Toolchain- / Workflow-Abfolge:</strong>\n<ol class=\"fig-list\"><li><em>Cluster- &amp; Systemdefinition:</em> Deklaration der Software-Cluster (<code>CpSoftwareCluster</code>) und Zusammenführung im zentralen <code>System</code>.\n</li><li><em>Timing-Allokation:</em> Definition von <code>SystemTiming</code>-Instanzen zur Festlegung von Inter-Cluster-Latenzen, Scheduling-Restriktionen und PDU-/Bus-Transferzeiten.\n</li><li><em>Varianten- und Split-Auflösung:</em> AUTOSAR-Authoring-Tools mergen gesplittete ARXMLs (<code>«atpSplitable»</code>) und evaluieren Variant-Konditionen (<code>«atpVariation»</code>), bevor Timing-Verifikationswerkzeuge die Ausführbarkeit validieren.\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>System- &amp; Integrationsarchitektur:</strong> \n<ul class=\"fig-list\"><li>Die Latenzanalyse zwischen Runnables zweier unterschiedlicher <code>CpSoftwareCluster</code> erfordert zwingend eine gemeinsame <code>SystemTiming</code>-Instanz, die das übergeordnete <code>System</code> referenziert.\n</li><li>Fehlt die Referenz <code>+swCluster</code>, können Timing-Tools keine korrekten modellbasierten Latenzprüfungen für modulare BSW-/Applikations-Cluster durchführen.\n</li></ul>\n</li><li><strong>Multi-Vendor- &amp; Splitable-Handling:</strong>\n<ul class=\"fig-list\"><li>Durch <code>«atpSplitable»</code> können Tier-1-Zulieferer ihre jeweiligen Cluster separat beschreiben. Der Integrator verknüpft diese im System-Extract, ohne die originalen ARXML-Dateien der Cluster modifizieren zu müssen.\n</li></ul>\n</li><li><strong>Variantenmanagement:</strong>\n<ul class=\"fig-list\"><li>Da <code>+swCluster</code> variabel ist (<code>«atpVariation»</code>), müssen Timing-Spezifikationen auf Systemebene gegen alle gültigen Variantenkonfigurationen geprüft werden. Nicht vorhandene Cluster dürfen keine unauflösbaren Timing-Abhängigkeiten in Event Chains hinterlassen.\n</li></ul>\n</li><li><strong>Einfluss auf Implementierung &amp; Stack:</strong>\n<ul class=\"fig-list\"><li>Keine direkte C-API-Wirkung auf Treiber (MCAL/BSW).\n</li><li>Indirekte normative Wirkung auf Generatoren (RTE, OS): Die aus dem <code>SystemTiming</code> abgeleiteten Constraints determinieren Task-Prioritäten, Task-Perioden, Offset-Vorgaben und Schwellwerte für das Execution Time Monitoring im OS.\n</li></ul>\n</li></ul>"}, {"id": "FIG-951783818f647bb3", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR System Template / Timing Extensions View).\n</li><li><strong>Technischer Zweck:</strong> Formale Verankerung der systemweiten Timing-Spezifikation (<code>SystemTiming</code>) an das Gesamtsystem (<code>System</code>) und dessen modulare Software-Partitionen (<code>CpSoftwareCluster</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Ermöglicht die Spezifikation von zeitlichen Anforderungen (End-to-End-Latenzen, Event Chains, Synchronisationsbudgets) über die Grenzen unabhängig aktualisierbarer bzw. verteilter Software-Cluster hinweg.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>SystemTiming</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>TimingExtension</code>.\n</li><li><em>Funktion:</em> Container für systemweite Timing-Beschreibungen (Ereignisse, Ereignisketten, Timing Constraints auf System- und Netzwerkebene).\n</li></ul>\n</li><li><strong><code>System</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>ARElement</code> und <code>AtpStructureElement</code>.\n</li><li><em>Funktion:</em> Wurzel-Entität der AUTOSAR-Systembeschreibung; aggregiert Topologie, Software-Composition, Signal-/PDU-Mappings und Systemkonfiguration.\n</li></ul>\n</li><li><strong><code>CpSoftwareCluster</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>ARElement</code>.\n</li><li><em>Attribute:</em> <code>+ softwareClusterId: PositiveInteger [0..1]</code> (eindeutiger numerischer Bezeichner des Software-Clusters).\n</li><li><em>Funktion:</em> Repräsentiert einen autark kompilierbaren, linkbaren oder via OTA aktualisierbaren Classic-Platform-Software-Cluster (logische Software-Partition).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>SystemTiming</code> → <code>System</code>: Unidirektionale Referenz <code>+system</code> mit Kardinalität <code>0..1</code> (eine <code>SystemTiming</code>-Instanz kann optional maximal einem definierten <code>System</code> zugeordnet sein).\n</li><li><code>System</code> → <code>CpSoftwareCluster</code>: Unidirektionale Referenz <code>+swCluster</code> mit Kardinalität <code>0..*</code>.\n</li><li><strong>Stereotypen auf <code>+swCluster</code>:</strong>\n<ul class=\"fig-list\"><li><code>«atpSplitable»</code>: Die Zuordnung von Clustern zum System kann physisch über separate ARXML-Dateien/Lieferartefakte verteilt (gesplittet) werden.\n</li><li><code>«atpVariation»</code>: Die Assoziation unterliegt der AUTOSAR-Variantentheorie (Bindung über Variant Condition Formulas zur Pre-Compile-, Link- oder Post-Build-Zeit).\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Charakter:</strong> Kein Laufzeit-Sequenzablauf. Es handelt sich um ein rein deklaratives Entwurfszeit-Modell für den ARXML-Datenaustausch.\n</li><li><strong>Toolchain- / Workflow-Abfolge:</strong>\n<ol class=\"fig-list\"><li><em>Cluster- &amp; Systemdefinition:</em> Deklaration der Software-Cluster (<code>CpSoftwareCluster</code>) und Zusammenführung im zentralen <code>System</code>.\n</li><li><em>Timing-Allokation:</em> Definition von <code>SystemTiming</code>-Instanzen zur Festlegung von Inter-Cluster-Latenzen, Scheduling-Restriktionen und PDU-/Bus-Transferzeiten.\n</li><li><em>Varianten- und Split-Auflösung:</em> AUTOSAR-Authoring-Tools mergen gesplittete ARXMLs (<code>«atpSplitable»</code>) und evaluieren Variant-Konditionen (<code>«atpVariation»</code>), bevor Timing-Verifikationswerkzeuge die Ausführbarkeit validieren.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>System- &amp; Integrationsarchitektur:</strong> \n<ul class=\"fig-list\"><li>Die Latenzanalyse zwischen Runnables zweier unterschiedlicher <code>CpSoftwareCluster</code> erfordert eine gemeinsame <code>SystemTiming</code>-Instanz, die das übergeordnete <code>System</code> referenziert. Durch die Kardinalität <code>0..1</code> kann eine Timing-Extension auch unabhängig von einer konkreten Systembeistellung deklariert werden.\n</li><li>Fehlt die Referenz <code>+swCluster</code>, können Timing-Tools keine modellbasierten Latenzprüfungen für modulare BSW-/Applikations-Cluster durchführen.\n</li><li>Das optionale Attribut <code>softwareClusterId</code> ermöglicht die formale Zuordnung von Timing-Artefakten zu spezifisch adressierbaren Clustern.\n</li></ul>\n</li><li><strong>Multi-Vendor- &amp; Splitable-Handling:</strong>\n<ul class=\"fig-list\"><li>Durch <code>«atpSplitable»</code> können Tier-1-Zulieferer ihre jeweiligen Cluster separat beschreiben. Der Integrator verknüpft diese im System-Extract, ohne dass Konflikte in der Clusterzuordnung entstehen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-1f0e4b11ee109443", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR System Template / Timing Extensions View).\n</li><li><strong>Technischer Zweck:</strong> Formale Verankerung der systemweiten Timing-Spezifikation (<code>SystemTiming</code>) an das Gesamtsystem (<code>System</code>) und dessen modulare Software-Partitionen (<code>CpSoftwareCluster</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Ermöglicht die Spezifikation von zeitlichen Anforderungen (End-to-End-Latenzen, Event Chains, Synchronisationsbudgets) über die Grenzen unabhängig aktualisierbarer bzw. verteilter Software-Cluster hinweg.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>SystemTiming</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>TimingExtension</code>.\n</li><li><em>Funktion:</em> Container für systemweite Timing-Beschreibungen (Ereignisse, Ereignisketten, Timing Constraints auf System- und Netzwerkebene).\n</li></ul>\n</li><li><strong><code>System</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>ARElement</code>, <code>AtpStructureElement</code> und <code>UploadableDesignElement</code>.\n</li><li><em>Funktion:</em> Wurzel-Entität der AUTOSAR-Systembeschreibung sowie uploadbares Design-Element; aggregiert Topologie, Software-Composition, Signal-/PDU-Mappings und Systemkonfiguration.\n</li></ul>\n</li><li><strong><code>CpSoftwareCluster</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>ARElement</code>.\n</li><li><em>Attribute:</em> <code>+ softwareClusterId: PositiveInteger [0..1]</code> (eindeutiger numerischer Bezeichner des Software-Clusters).\n</li><li><em>Funktion:</em> Repräsentiert einen autark kompilierbaren, linkbaren oder via OTA aktualisierbaren Classic-Platform-Software-Cluster (logische Software-Partition).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>SystemTiming</code> → <code>System</code>: Unidirektionale Referenz <code>+system</code> mit Kardinalität <code>0..1</code> (eine <code>SystemTiming</code>-Instanz kann optional maximal einem definierten <code>System</code> zugeordnet sein).\n</li><li><code>System</code> → <code>CpSoftwareCluster</code>: Unidirektionale Referenz <code>+swCluster</code> mit Kardinalität <code>0..*</code>.\n</li><li><strong>Stereotypen auf <code>+swCluster</code>:</strong>\n<ul class=\"fig-list\"><li><code>«atpSplitable»</code>: Die Zuordnung von Clustern zum System kann physisch über separate ARXML-Dateien/Lieferartefakte verteilt (gesplittet) werden.\n</li><li><code>«atpVariation»</code>: Die Assoziation unterliegt der AUTOSAR-Variantentheorie (Bindung über Variant Condition Formulas zur Pre-Compile-, Link- oder Post-Build-Zeit).\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Charakter:</strong> Kein Laufzeit-Sequenzablauf. Es handelt sich um ein rein deklaratives Entwurfszeit-Modell für den ARXML-Datenaustausch.\n</li><li><strong>Toolchain- / Workflow-Abfolge:</strong>\n<ol class=\"fig-list\"><li><em>Cluster- &amp; Systemdefinition:</em> Deklaration der Software-Cluster (<code>CpSoftwareCluster</code>) und Zusammenführung im zentralen <code>System</code>.\n</li><li><em>Timing-Allokation:</em> Definition von <code>SystemTiming</code>-Instanzen zur Festlegung von Inter-Cluster-Latenzen, Scheduling-Restriktionen und PDU-/Bus-Transferzeiten.\n</li><li><em>Varianten- und Split-Auflösung:</em> AUTOSAR-Authoring-Tools mergen gesplittete ARXMLs (<code>«atpSplitable»</code>) und evaluieren Variant-Konditionen (<code>«atpVariation»</code>), bevor Timing-Verifikationswerkzeuge die Ausführbarkeit validieren.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>System- &amp; Integrationsarchitektur:</strong> \n<ul class=\"fig-list\"><li>Die Latenzanalyse zwischen Runnables zweier unterschiedlicher <code>CpSoftwareCluster</code> erfordert eine gemeinsame <code>SystemTiming</code>-Instanz, die das übergeordnete <code>System</code> referenziert. Durch die Kardinalität <code>0..1</code> kann eine Timing-Extension auch unabhängig von einer konkreten Systembeistellung deklariert werden.\n</li><li>Fehlt die Referenz <code>+swCluster</code>, können Timing-Tools keine modellbasierten Latenzprüfungen für modulare BSW-/Applikations-Cluster durchführen.\n</li><li>Das optionale Attribut <code>softwareClusterId</code> ermöglicht die formale Zuordnung von Timing-Artefakten zu spezifisch adressierbaren Clustern.\n</li></ul>\n</li><li><strong>Multi-Vendor- &amp; Splitable-Handling:</strong>\n<ul class=\"fig-list\"><li>Durch <code>«atpSplitable»</code> können Tier-1-Zulieferer ihre jeweiligen Cluster separat beschreiben. Der Integrator verknüpft diese im System-Extract, ohne dass Konflikte in der Clusterzuordnung entstehen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-95978e10187ef3bb", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR System Template / Timing Extensions View).\n</li><li><strong>Technischer Zweck:</strong> Formale Verankerung der systemweiten Timing-Spezifikation (<code>SystemTiming</code>) an das Gesamtsystem (<code>System</code>) und dessen modulare Software-Partitionen (<code>CpSoftwareCluster</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Ermöglicht die Spezifikation von zeitlichen Anforderungen (End-to-End-Latenzen, Event Chains, Synchronisationsbudgets) über die Grenzen unabhängig aktualisierbarer bzw. verteilter Software-Cluster hinweg.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>SystemTiming</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>TimingExtension</code>.\n</li><li><em>Funktion:</em> Container für systemweite Timing-Beschreibungen (Ereignisse, Ereignisketten, Timing Constraints auf System- und Netzwerkebene).\n</li></ul>\n</li><li><strong><code>System</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>ARElement</code>, <code>AtpStructureElement</code> und <code>UploadableDesignElement</code>.\n</li><li><em>Funktion:</em> Wurzel-Entität der AUTOSAR-Systembeschreibung sowie uploadbares Design-Element; aggregiert Topologie, Software-Composition, Signal-/PDU-Mappings und Systemkonfiguration.\n</li></ul>\n</li><li><strong><code>CpSoftwareCluster</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>ARElement</code>.\n</li><li><em>Attribute:</em> <code>+ softwareClusterId: PositiveInteger [0..1]</code> (eindeutiger numerischer Bezeichner des Software-Clusters).\n</li><li><em>Funktion:</em> Repräsentiert einen autark kompilierbaren, linkbaren oder via OTA aktualisierbaren Classic-Platform-Software-Cluster (logische Software-Partition).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>SystemTiming</code> → <code>System</code>: Unidirektionale Referenz <code>+system</code> mit Kardinalität <code>0..1</code> (eine <code>SystemTiming</code>-Instanz kann optional maximal einem definierten <code>System</code> zugeordnet sein).\n</li><li><code>System</code> → <code>CpSoftwareCluster</code>: Unidirektionale Referenz <code>+swCluster</code> mit Kardinalität <code>0..*</code>.\n</li><li><strong>Stereotypen auf <code>+swCluster</code>:</strong>\n<ul class=\"fig-list\"><li><code>«atpSplitable»</code>: Die Zuordnung von Clustern zum System kann physisch über separate ARXML-Dateien/Lieferartefakte verteilt (gesplittet) werden.\n</li><li><code>«atpVariation»</code>: Die Assoziation unterliegt der AUTOSAR-Variantentheorie (Bindung über Variant Condition Formulas zur Pre-Compile-, Link- oder Post-Build-Zeit).\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Charakter:</strong> Kein Laufzeit-Sequenzablauf. Es handelt sich um ein rein deklaratives Entwurfszeit-Modell für den ARXML-Datenaustausch.\n</li><li><strong>Toolchain- / Workflow-Abfolge:</strong>\n<ol class=\"fig-list\"><li><em>Cluster- &amp; Systemdefinition:</em> Deklaration der Software-Cluster (<code>CpSoftwareCluster</code>) und Zusammenführung im zentralen <code>System</code>.\n</li><li><em>Timing-Allokation:</em> Definition von <code>SystemTiming</code>-Instanzen zur Festlegung von Inter-Cluster-Latenzen, Scheduling-Restriktionen und PDU-/Bus-Transferzeiten.\n</li><li><em>Varianten- und Split-Auflösung:</em> AUTOSAR-Authoring-Tools mergen gesplittete ARXMLs (<code>«atpSplitable»</code>) und evaluieren Variant-Konditionen (<code>«atpVariation»</code>), bevor Timing-Verifikationswerkzeuge die Ausführbarkeit validieren.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>System- &amp; Integrationsarchitektur:</strong> \n<ul class=\"fig-list\"><li>Die Latenzanalyse zwischen Runnables zweier unterschiedlicher <code>CpSoftwareCluster</code> erfordert eine gemeinsame <code>SystemTiming</code>-Instanz, die das übergeordnete <code>System</code> referenziert. Durch die Kardinalität <code>0..1</code> kann eine Timing-Extension auch unabhängig von einer konkreten Systembeistellung deklariert werden.\n</li><li>Fehlt die Referenz <code>+swCluster</code>, können Timing-Tools keine modellbasierten Latenzprüfungen für modulare BSW-/Applikations-Cluster durchführen.\n</li><li>Das optionale Attribut <code>softwareClusterId</code> ermöglicht die formale Zuordnung von Timing-Artefakten zu spezifisch adressierbaren Clustern.\n</li></ul>\n</li><li><strong>Multi-Vendor- &amp; Splitable-Handling:</strong>\n<ul class=\"fig-list\"><li>Durch <code>«atpSplitable»</code> können Tier-1-Zulieferer ihre jeweiligen Cluster separat beschreiben. Der Integrator verknüpft diese im System-Extract, ohne dass Konflikte in der Clusterzuordnung entstehen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-008b9728c6b1e03e", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR System Template / Timing Extensions View).\n</li><li><strong>Technischer Zweck:</strong> Formale Verankerung der systemweiten Timing-Spezifikation (<code>SystemTiming</code>) an das Gesamtsystem (<code>System</code>) und dessen modulare Software-Partitionen (<code>CpSoftwareCluster</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Ermöglicht die Spezifikation von zeitlichen Anforderungen (End-to-End-Latenzen, Event Chains, Synchronisationsbudgets) über die Grenzen unabhängig aktualisierbarer bzw. verteilter Software-Cluster hinweg.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>SystemTiming</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>TimingExtension</code>.\n</li><li><em>Funktion:</em> Container für systemweite Timing-Beschreibungen (Ereignisse, Ereignisketten, Timing Constraints auf System- und Netzwerkebene).\n</li></ul>\n</li><li><strong><code>System</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>ARElement</code>, <code>AtpStructureElement</code> und <code>UploadableDesignElement</code>.\n</li><li><em>Funktion:</em> Wurzel-Entität der AUTOSAR-Systembeschreibung sowie uploadbares Design-Element; aggregiert Topologie, Software-Composition, Signal-/PDU-Mappings und Systemkonfiguration.\n</li></ul>\n</li><li><strong><code>CpSoftwareCluster</code></strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt von <code>ARElement</code>.\n</li><li><em>Attribute:</em> <code>+ softwareClusterId: PositiveInteger [0..1]</code> (eindeutiger numerischer Bezeichner des Software-Clusters).\n</li><li><em>Funktion:</em> Repräsentiert einen autark kompilierbaren, linkbaren oder via OTA aktualisierbaren Classic-Platform-Software-Cluster (logische Software-Partition).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Multiplizitäten:</strong>\n<ul class=\"fig-list\"><li><code>SystemTiming</code> → <code>System</code>: Unidirektionale Referenz <code>+system</code> mit Kardinalität <code>0..1</code> (eine <code>SystemTiming</code>-Instanz kann optional maximal einem definierten <code>System</code> zugeordnet sein).\n</li><li><code>System</code> → <code>CpSoftwareCluster</code>: Unidirektionale Referenz <code>+swCluster</code> mit Kardinalität <code>0..*</code>.\n</li><li><strong>Stereotypen auf <code>+swCluster</code>:</strong>\n<ul class=\"fig-list\"><li><code>«atpSplitable»</code>: Die Zuordnung von Clustern zum System kann physisch über separate ARXML-Dateien/Lieferartefakte verteilt (gesplittet) werden.\n</li><li><code>«atpVariation»</code>: Die Assoziation unterliegt der AUTOSAR-Variantentheorie (Bindung über Variant Condition Formulas zur Pre-Compile-, Link- oder Post-Build-Zeit).\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Charakter:</strong> Kein Laufzeit-Sequenzablauf. Es handelt sich um ein rein deklaratives Entwurfszeit-Modell für den ARXML-Datenaustausch.\n</li><li><strong>Toolchain- / Workflow-Abfolge:</strong>\n<ol class=\"fig-list\"><li><em>Cluster- &amp; Systemdefinition:</em> Deklaration der Software-Cluster (<code>CpSoftwareCluster</code>) und Zusammenführung im zentralen <code>System</code>.\n</li><li><em>Timing-Allokation:</em> Definition von <code>SystemTiming</code>-Instanzen zur Festlegung von Inter-Cluster-Latenzen, Scheduling-Restriktionen und PDU-/Bus-Transferzeiten.\n</li><li><em>Varianten- und Split-Auflösung:</em> AUTOSAR-Authoring-Tools mergen gesplittete ARXMLs (<code>«atpSplitable»</code>) und evaluieren Variant-Konditionen (<code>«atpVariation»</code>), bevor Timing-Verifikationswerkzeuge die Ausführbarkeit validieren.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>System- &amp; Integrationsarchitektur:</strong> \n<ul class=\"fig-list\"><li>Die Latenzanalyse zwischen Runnables zweier unterschiedlicher <code>CpSoftwareCluster</code> erfordert eine gemeinsame <code>SystemTiming</code>-Instanz, die das übergeordnete <code>System</code> referenziert. Durch die Kardinalität <code>0..1</code> kann eine Timing-Extension auch unabhängig von einer konkreten Systembeistellung deklariert werden.\n</li><li>Fehlt die Referenz <code>+swCluster</code>, können Timing-Tools keine modellbasierten Latenzprüfungen für modulare BSW-/Applikations-Cluster durchführen.\n</li><li>Das optionale Attribut <code>softwareClusterId</code> ermöglicht die formale Zuordnung von Timing-Artefakten zu spezifisch adressierbaren Clustern.\n</li></ul>\n</li><li><strong>Multi-Vendor- &amp; Splitable-Handling:</strong>\n<ul class=\"fig-list\"><li>Durch <code>«atpSplitable»</code> können Tier-1-Zulieferer ihre jeweiligen Cluster separat beschreiben. Der Integrator verknüpft diese im System-Extract, ohne dass Konflikte in der Clusterzuordnung entstehen.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-69d67eebda036252", "to": "FIG-951783818f647bb3", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>SystemTiming</code>: Klassenname ohne Paketpräfix <code>Timing::</code>.\n</li><li><code>System</code>: Klassenname ohne Paketpräfix <code>SystemTemplate::</code>.\n</li><li><code>SystemTiming</code> → <code>System</code>: Multiplizität an der Assoziation <code>+system</code> von <code>1</code> auf <code>0..1</code> gelockert.\n</li><li><code>CpSoftwareCluster</code>: Klassenname ohne Paketpräfix <code>SoftwareCluster::</code>.\n</li><li><code>CpSoftwareCluster</code>: Attribut <code>+ softwareClusterId: PositiveInteger [0..1]</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-951783818f647bb3", "to": "FIG-1f0e4b11ee109443", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>System</code>: Generalisierung/Klassifikation um <code>UploadableDesignElement</code> ergänzt.\n</li></ul>"}, {"from": "FIG-1f0e4b11ee109443", "to": "FIG-95978e10187ef3bb", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-95978e10187ef3bb", "to": "FIG-008b9728c6b1e03e", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
